                if (c3 <= 14) {
                    {
                        api.file_text_write_string(self, other, self.vars[g.VAR_file], " YETI KING  | ");
                        break :sw3;
                    }
                }
                if (c3 <= 15) {
                    {
                        api.file_text_write_string(self, other, self.vars[g.VAR_file], " ALIEN      | ");
                        break :sw3;
                    }
                }
                if (c3 <= 16) {
                    {
                        api.file_text_write_string(self, other, self.vars[g.VAR_file], " UFO        | ");
                        break :sw3;
                    }
                }
                if (c3 <= 17) {
                    {
                        api.file_text_write_string(self, other, self.vars[g.VAR_file], " ALIEN BOSS | ");
                        break :sw3;
                    }
                }
                if (c3 <= 18) {
                    {
                        api.file_text_write_string(self, other, self.vars[g.VAR_file], " HAWKMAN    | ");
                        break :sw3;
                    }
                }
                if (c3 <= 19) {
                    {
                        api.file_text_write_string(self, other, self.vars[g.VAR_file], " SHOPKEEPER | ");
                        break :sw3;
                    }
                }
                if (c3 <= 20) {
                    {
                        api.file_text_write_string(self, other, self.vars[g.VAR_file], " TOMB LORD  | ");
                        break :sw3;
                    }
                }
                if (c3 <= 21) {
                    {
                        api.file_text_write_string(self, other, self.vars[g.VAR_file], " OLMEC      | ");
                        break :sw3;
                    }
                }
            }
        }
        self.vars[g.VAR_totalKills] = rt.real(rt.add(rt.vreal(self.vars[g.VAR_totalKills]), rt.aget(g.gvals[g.GV_enemyKills], self.vars[g.VAR_i])));
        api.file_text_write_string(self, other, self.vars[g.VAR_file], api.string(self, other, rt.aget(g.gvals[g.GV_enemyKills], self.vars[g.VAR_i])));
        api.file_text_writeln(self, other, self.vars[g.VAR_file]);
        if (rt.eq(self.vars[g.VAR_i], 8.0)) {
            if (rt.eq(g.globals.totalMonkeyKills, 0.0)) {
                api.file_text_write_string(self, other, self.vars[g.VAR_file], " ???        | ");
            } else {
                api.file_text_write_string(self, other, self.vars[g.VAR_file], " MONKEY     | ");
            }
            self.vars[g.VAR_totalKills] = (self.vars[g.VAR_totalKills] + g.globals.totalMonkeyKills);
            api.file_text_write_string(self, other, self.vars[g.VAR_file], rt.realStr(g.globals.totalMonkeyKills));
            api.file_text_writeln(self, other, self.vars[g.VAR_file]);
        }
    }
    api.file_text_write_string(self, other, self.vars[g.VAR_file], "------------+------------");
    api.file_text_writeln(self, other, self.vars[g.VAR_file]);
    api.file_text_write_string(self, other, self.vars[g.VAR_file], " TOTAL      | ");
    api.file_text_write_string(self, other, self.vars[g.VAR_file], rt.realStr(self.vars[g.VAR_totalKills]));
    api.file_text_writeln(self, other, self.vars[g.VAR_file]);
    api.file_text_close(self, other, self.vars[g.VAR_file]);
}
